SELECT 
FROM outbound_order

    is_deleted = 0
    AND order_no LIKE CONCAT('%', #{orderNo}, '%')
    AND status = #{status}
    AND create_time >= #{startTime}
    AND create_time <= #{endTime}

ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM outbound_order

    is_deleted = 0
    AND order_no LIKE CONCAT('%', #{orderNo}, '%')
    AND status = #{status}
    AND create_time >= #{startTime}
    AND create_time <= #{endTime}
